where id = #{id}

mapper.select:
SELECT * FROM orders


        AND user_id = #{userId}


        AND status = #{status}


        AND number LIKE CONCAT('%', #{number}, '%')


        AND phone LIKE CONCAT('%', #{phone}, '%')


        AND order_time >= #{beginTime}


        AND order_time <= #{endTime}


ORDER BY order_time DESC

select count(*)
from orders
where status = #{status}

SELECT SUM(amount)
FROM orders


        AND order_time >= #{begin}


        AND order_time <= #{end}


        AND status = #{status}

SELECT DATE(create_time) AS statDate, COUNT(id) AS userCount
FROM user
WHERE create_time >= #{begin}
  AND create_time <= #{end}
GROUP BY DATE(create_time)
ORDER BY statDate

SELECT COUNT(id)
FROM user
WHERE create_time < #{end}

SELECT COUNT(id)
FROM orders


        AND order_time >= #{begin}


        AND order_time <= #{end}


        AND status = #{status}

select od.name, sum(od.number) as number from orders o, order_detail od
o.id = od.order_id AND o.status = 5
AND o.order_time >= #{begin}
AND o.order_time <= #{end}
group by od.name order by number desc limit 0,10
